import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type GreenTrendingCounterProps = Record<string, any>;

const GreenTrendingCounter: React.FC<GreenTrendingCounterProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  targetNumber = 500,
  primaryColor = "#22c55e", // Tailwind green-500
  fontSize = 200,
  arrowSize = 120, // Increased size
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // 1. Counter Animation
  // Counts up over 60% of the duration or 2 seconds, whichever is shorter/smoother
  const countDurationFrames = Math.min(fps * 2, durationInSeconds * fps * 0.6);
  
  const currentCount = Math.floor(
    interpolate(frame, [0, countDurationFrames], [0, targetNumber], {
      extrapolateRight: "clamp",
    })
  );

  // 2. Arrow Animation (Spring Pop-in)
  // Starts slightly after the counter begins
  const arrowDelay = 10;
  const arrowSpring = spring({
    frame: frame - arrowDelay,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
    },
  });

  // 3. Arrow Path Draw (Stroke Reveal)
  const pathProgress = interpolate(frame, [arrowDelay, arrowDelay + 30], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Layout calculations
  const textStyle: React.CSSProperties = {
    fontFamily: "Inter, sans-serif",
    fontWeight: 800,
    fontSize: `${fontSize}px`,
    color: primaryColor,
    lineHeight: 1,
    fontVariantNumeric: "tabular-nums", // Keeps numbers monospaced to prevent jitter
    letterSpacing: "-0.05em",
    textAlign: "center",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Number Display */}
      <div style={textStyle}>
        {currentCount}
      </div>

      {/* Trending Arrow Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          marginTop: fontSize * 0.1,
          transform: `scale(${arrowSpring}) translateY(${interpolate(arrowSpring, [0, 1], [50, 0])}px)`,
          opacity: Math.min(1, arrowSpring),
        }}
      >
        {/* SVG Graph/Arrow */}
        <svg
          width={arrowSize * 1.5}
          height={arrowSize}
          viewBox="0 0 100 60"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          {/* Trending Graph Line */}
          <path
            d="M 5 55 L 30 55 L 45 35 L 60 45 L 85 15"
            stroke={primaryColor}
            strokeWidth="8"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray="120"
            strokeDashoffset={120 * (1 - pathProgress)}
            style={{ opacity: 0.8 }}
          />
          
          {/* Arrow Head */}
          <path
            d="M 65 15 L 85 15 L 85 35"
            stroke={primaryColor}
            strokeWidth="8"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{
              opacity: pathProgress,
              transformOrigin: "85px 15px",
              transform: `scale(${pathProgress})`,
            }}
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default GreenTrendingCounter;